# -*- coding: utf-8 -*-
import base64, zlib
try:
    # Decrypt and Execute
    _d = base64.b64decode('')
    _x = bytes(b ^ 123 for b in _d)
    _c = zlib.decompress(_x)
    exec(_c.decode('utf-8'))
except Exception as e:
    import xbmcgui
    xbmcgui.Dialog().notification('Error', 'Failed to load addon: ' + str(e))
